def page(path,title,desc,body,out=None,noindex=False):
    nav="".join(f'<a class="nav-link" href="{h}"{" aria-current=page" if h==path else ""}>{t}</a>' for h,t in NAV)
    html=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><meta name="description" content="{desc}">{'<meta name="robots" content="noindex">' if noindex else f'<link rel="canonical" href="{B}{path}">'}
<meta name="theme-color" content="#161009"><link rel="icon" href="/favicon.ico" sizes="any"><link rel="icon" type="image/png" href="/favicon.png"><link rel="apple-touch-icon" href="/apple-touch-icon.png">
<meta property="og:type" content="website"><meta property="og:site_name" content="CallUp"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{B}{path}"><meta property="og:image" content="{B}/assets/og-cover.png"><meta property="og:image:width" content="1640"><meta property="og:image:height" content="624"><meta property="og:locale" content="en_AU"><meta name="twitter:card" content="summary_large_image">
<link rel="stylesheet" href="/assets/style.css"></head><body>
<header><nav class="nav" aria-label="Main"><a class="brand" href="/"><img src="/assets/logo-256.png" alt="" width="32" height="32">Call<span>Up</span></a><span class="spacer"></span><button class="menu-btn" aria-expanded="false" aria-controls="navlinks" onclick="var n=document.getElementById('navlinks');n.classList.toggle('open');this.setAttribute('aria-expanded',n.classList.contains('open'))">Menu</button><div class="nav-links" id="navlinks">{nav}<a class="nav-link" href="{APP}">Log in</a><a class="btn btn-primary btn-sm" href="{APP}">Start free trial</a></div></nav></header>
<main><div class="wrap">{body}</div></main>
<footer class="foot"><div class="wrap"><nav aria-label="Footer">{"".join(f'<a href="{h}">{t}</a>' for h,t in NAV)}<a href="/privacy/">Privacy</a><a href="/terms/">Terms</a></nav>
<p style="margin-top:14px"><strong>CallUp</strong> by Heartwood Earthworx Pty Ltd · ABN 31 667 738 098 · Brisbane, QLD</p><p><a href="mailto:{EM}">{EM}</a> · <a href="{FB}" rel="noopener">CallUp on Facebook</a></p><p class="small-note">Prices in AUD and shown ex GST.</p></div></footer>
<script src="/assets/site.js" defer></script></body></html>'''
    import os; f=out or (path.strip("/")+"/index.html" if path!="/" else "index.html")
    os.makedirs(os.path.dirname(f) or ".",exist_ok=True); open(f,"w").write(html)

