def fig(n,cap,w,h,cls="",caption=False):
    kind="desk" if w>h else "phone"
    fc=f'<figcaption>{cap}</figcaption>' if caption else ""
    return f'<figure class="shot {kind} {cls}"><div class="frame"><img src="/assets/shots/{n}.webp" alt="CallUp screenshot. {cap}" width="{w}" height="{h}" loading="lazy" decoding="async"></div>{fc}</figure>'
